interactions.sample_code:
function merge(left, right) {
  while (!left_done() && !right_done()) {
    if (less_eq_left()) { take_left(); }
    else { take_right(); }
  }
  if (left_done()) { finish("right"); }
  else { finish("left"); }
}

interactions.buggy_code:
function merge(left, right) {
  while (!left_done() && !right_done()) {
    // BUG: strict < breaks stability — on a tie the right element wins,
    // so the right-half 2 is emitted before the left-half 2.
    if (left_front() < right_front()) { take_left(); }
    else { take_right(); }
  }
  if (left_done()) { finish("right"); }
  else { finish("left"); }
}

